fn unit_metadata() {
    let info = ElectricCurrent::<f64>::INFO;
    assert_eq!(info.name, "ElectricCurrent");
    assert_eq!(info.units.len(), ElectricCurrentUnit::ALL.len());
    for (&unit, unit_info) in ElectricCurrentUnit::ALL.iter().zip(info.units) {
        assert_eq!(unit.info(), unit_info);
        assert_eq!(format!("{unit:?}"), unit_info.singular);
        assert_eq!(unit.abbreviation(), unit_info.abbreviation);
        assert_eq!(unit.all_abbreviations(), unit_info.abbreviations);
    }
    assert_eq!(info.base_unit, ElectricCurrentUnit::Ampere.info());
}

#[test]
fn new_and_convert_to_match_named_methods() {
    let v = 1234.5;
    assert_eq!(
        ElectricCurrent::new(v, ElectricCurrentUnit::Ampere),
        ElectricCurrent::from_amperes(v)
    );
    assert_eq!(
        ElectricCurrent::from_base(v).convert_to(ElectricCurrentUnit::Ampere),
        ElectricCurrent::from_base(v).as_amperes()
    );
    assert_eq!(
        ElectricCurrent::new(v, ElectricCurrentUnit::Femtoampere),
        ElectricCurrent::from_femtoamperes(v)
    );
    assert_eq!(
        ElectricCurrent::from_base(v).convert_to(ElectricCurrentUnit::Femtoampere),
        ElectricCurrent::from_base(v).as_femtoamperes()
    );
    assert_eq!(
        ElectricCurrent::new(v, ElectricCurrentUnit::Picoampere),
        ElectricCurrent::from_picoamperes(v)
    );
    assert_eq!(
        ElectricCurrent::from_base(v).convert_to(ElectricCurrentUnit::Picoampere),
        ElectricCurrent::from_base(v).as_picoamperes()
    );
    assert_eq!(
        ElectricCurrent::new(v, ElectricCurrentUnit::Nanoampere),
        ElectricCurrent::from_nanoamperes(v)
    );
    assert_eq!(
        ElectricCurrent::from_base(v).convert_to(ElectricCurrentUnit::Nanoampere),
        ElectricCurrent::from_base(v).as_nanoamperes()
    );
    assert_eq!(
        ElectricCurrent::new(v, ElectricCurrentUnit::Microampere),
        ElectricCurrent::from_microamperes(v)
    );
    assert_eq!(
        ElectricCurrent::from_base(v).convert_to(ElectricCurrentUnit::Microampere),
        ElectricCurrent::from_base(v).as_microamperes()
    );
    assert_eq!(
        ElectricCurrent::new(v, ElectricCurrentUnit::Milliampere),
        ElectricCurrent::from_milliamperes(v)
    );
    assert_eq!(
        ElectricCurrent::from_base(v).convert_to(ElectricCurrentUnit::Milliampere),
        ElectricCurrent::from_base(v).as_milliamperes()
    );
    assert_eq!(
        ElectricCurrent::new(v, ElectricCurrentUnit::Centiampere),
        ElectricCurrent::from_centiamperes(v)
    );
    assert_eq!(
        ElectricCurrent::from_base(v).convert_to(ElectricCurrentUnit::Centiampere),
        ElectricCurrent::from_base(v).as_centiamperes()
    );
    assert_eq!(
        ElectricCurrent::new(v, ElectricCurrentUnit::Kiloampere),
        ElectricCurrent::from_kiloamperes(v)
    );
    assert_eq!(
        ElectricCurrent::from_base(v).convert_to(ElectricCurrentUnit::Kiloampere),
        ElectricCurrent::from_base(v).as_kiloamperes()
    );
    assert_eq!(
        ElectricCurrent::new(v, ElectricCurrentUnit::Megaampere),
        ElectricCurrent::from_megaamperes(v)
    );
    assert_eq!(
        ElectricCurrent::from_base(v).convert_to(ElectricCurrentUnit::Megaampere),
        ElectricCurrent::from_base(v).as_megaamperes()
    );
}

#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [ElectricCurrent; 9] = [
        ElectricCurrent::const_new(1234.5, ElectricCurrentUnit::Ampere),
        ElectricCurrent::const_new(1234.5, ElectricCurrentUnit::Femtoampere),
        ElectricCurrent::const_new(1234.5, ElectricCurrentUnit::Picoampere),
        ElectricCurrent::const_new(1234.5, ElectricCurrentUnit::Nanoampere),
        ElectricCurrent::const_new(1234.5, ElectricCurrentUnit::Microampere),
        ElectricCurrent::const_new(1234.5, ElectricCurrentUnit::Milliampere),
        ElectricCurrent::const_new(1234.5, ElectricCurrentUnit::Centiampere),
        ElectricCurrent::const_new(1234.5, ElectricCurrentUnit::Kiloampere),
        ElectricCurrent::const_new(1234.5, ElectricCurrentUnit::Megaampere),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(ElectricCurrentUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            ElectricCurrent::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in ElectricCurrentUnit::ALL {
            assert_eq!(
                ElectricCurrent::const_new(v, unit).as_base().to_bits(),
                ElectricCurrent::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = ElectricCurrent::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            ElectricCurrent::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in ElectricCurrentUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        ElectricCurrent::from_base(0.0).auto_unit().unit,
        ElectricCurrentUnit::Ampere
    );
}

